// spec: specs/session-auth.md (1.1) · кейс SA-04 · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.parent-b.spec.ts
// Только чтение (GET и RPC-чтения). PATCH/DELETE чужого ребёнка здесь сознательно не делаются.
import { test, expect } from '@playwright/test';
import { FAMILY_A_CHILDREN, NONEXISTENT_CHILD, PARENT_B, captureSupabase, ownChildren, rest, userHeaders } from './session-auth.helpers';

test.use({ storageState: PARENT_B });

/** Запросы, которые сравниваются: чужой id против несуществующего. */
const probes = (id: string) =>
  [
    { name: 'children', method: 'GET', path: `/rest/v1/children?id=eq.${id}&select=*` },
    { name: 'writing_attempts', method: 'GET', path: `/rest/v1/writing_attempts?child_id=eq.${id}&select=*&limit=5` },
    { name: 'rpc/current_levels', method: 'POST', path: '/rest/v1/rpc/current_levels', body: { p_child_id: id } },
    { name: 'rpc/child_profile', method: 'POST', path: '/rest/v1/rpc/child_profile', body: { p_child_id: id } },
    { name: 'rpc/next_activity', method: 'POST', path: '/rest/v1/rpc/next_activity', body: { p_child_id: id } },
  ] as const;

test.describe('Сессия и права — API', () => {
  test('Ребёнок чужой семьи отвечает так же, как несуществующий, без данных @desktop @prod-safe #a337fd', async ({ page, request }) => {
    const sb = await captureSupabase(page, '/children');
    const own = (await ownChildren(request, sb)).map((c) => c.id);

    for (const [nick, foreignId] of Object.entries(FAMILY_A_CHILDREN)) {
      expect(own, `${nick} не должен принадлежать parent-b`).not.toContain(foreignId);

      const foreign = probes(foreignId);
      const missing = probes(NONEXISTENT_CHILD);
      for (let i = 0; i < foreign.length; i++) {
        const f = foreign[i];
        const m = missing[i];
        const rf = await rest(request, sb.base, userHeaders(sb), f.method, f.path, 'body' in f ? f.body : undefined);
        const rm = await rest(request, sb.base, userHeaders(sb), m.method, m.path, 'body' in m ? m.body : undefined);
        const where = `${f.name} (${nick})`;

        // AC5 «דחייה שאינה חושפת קיום משאב»: чужой = несуществующий (код и тело совпадают)
        expect(rf.status, `${where}: код как у несуществующего (${rm.status}); ответ ${rf.text}`).toBe(rm.status);
        expect(rf.text, `${where}: тело как у несуществующего`).toBe(rm.text);

        // Допустимые ответы: 200 [] или 403 not_authorized; без полей ресурса
        if (rf.status === 200) {
          expect(JSON.parse(rf.text), `${where}: пустой ответ`).toEqual([]);
        } else {
          expect(rf.status, `${where}: ${rf.text}`).toBe(403);
          expect(JSON.parse(rf.text).message, where).toBe('not_authorized');
        }
        expect(rf.text, `${where}: нет id ребёнка в ответе`).not.toContain(foreignId);
        expect(rf.text, `${where}: нет имени ребёнка`).not.toContain(nick);
      }
    }
  });
});
